const meta = {
  component: Menubar,
  tags: ["autodocs"],
  parameters: {
    layout: "centered",
    docs: {
      description: {
        component: "## Usage

Use a persistent menu bar, as in desktop applications, for quick access to a consistent set of commands.

**Import:** `@/registry/erbium/ui/menubar`

## Usage

```tsx
import {
  Menubar,
  MenubarContent,
  MenubarGroup,
  MenubarItem,
  MenubarMenu,
  MenubarSeparator,
  MenubarShortcut,
  MenubarTrigger,
} from "@/registry/erbium/ui/menubar";
```

```tsx
<Menubar>
  <MenubarMenu>
    <MenubarTrigger>File</MenubarTrigger>
    <MenubarContent>
      <MenubarGroup>
        <MenubarItem>
          New Tab <MenubarShortcut hotkey="Mod+T" />
        </MenubarItem>
        <MenubarItem>New Window</MenubarItem>
      </MenubarGroup>
      <MenubarSeparator />
      <MenubarGroup>
        <MenubarItem>Share</MenubarItem>
        <MenubarItem>Print</MenubarItem>
      </MenubarGroup>
    </MenubarContent>
  </MenubarMenu>
</Menubar>
```

## Composition

Use the following composition to build a `Menubar`:

```text
Menubar
├── MenubarMenu
│   ├── MenubarTrigger
│   └── MenubarContent
│       ├── MenubarGroup
│       │   ├── MenubarLabel
│       │   ├── MenubarItem
│       │   └── MenubarItem
│       ├── MenubarSeparator
│       ├── MenubarGroup
│       │   ├── MenubarLabel
│       │   ├── MenubarCheckboxItem
│       │   └── MenubarCheckboxItem
│       ├── MenubarSeparator
│       ├── MenubarGroup
│       │   ├── MenubarLabel
│       │   └── MenubarRadioGroup
│       │       ├── MenubarRadioItem
│       │       └── MenubarRadioItem
│       └── MenubarSub
│           ├── MenubarSubTrigger
│           └── MenubarSubContent
│               └── MenubarGroup
│                   ├── MenubarLabel
│                   ├── MenubarItem
│                   └── MenubarItem
└── MenubarMenu
    ├── MenubarTrigger
    └── MenubarContent
        └── MenubarGroup
            ├── MenubarLabel
            ├── MenubarItem
            └── MenubarItem
```

## Base UI documentation

Explore the underlying primitives and their API reference.

- [Menu](https://base-ui.com/react/components/menu)
- [Menubar](https://base-ui.com/react/components/menubar)",
      },
    },
  },
} satisfies Meta<typeof Menubar>;

export default { ...meta, title: "Components/Menubar",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<{
  className: string;
  align: "start" | "center" | "end";
  itemVariant: "default" | "error";
  disabled: boolean;
}> = {
  args: { className: "", align: "start", itemVariant: "default", disabled: false },
  argTypes: {
    className: { control: "text" },
    align: { control: "select", options: ["start", "center", "end"] },
    itemVariant: { control: "select", options: ["default", "error"] },
    disabled: { control: "boolean" },
  },
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: PlaygroundSource },
    },
  },
  render: PlaygroundExample,
};

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: OverviewSource },
    },
  },
  render: OverviewExample,
};

export const Checkbox: Story = {
  parameters: {
    docs: {
      description: { story: "Use `MenubarCheckboxItem` for toggleable options." },
      source: { code: CheckboxSource },
    },
  },
  render: CheckboxExample,
};

export const Radio: Story = {
  parameters: {
    docs: {
      description: { story: "Use `MenubarRadioGroup` and `MenubarRadioItem` for single-select options." },
      source: { code: RadioSource },
    },
  },
  render: RadioExample,
};

export const Submenu: Story = {
  parameters: {
    docs: {
      description: { story: "Use `MenubarSub`, `MenubarSubTrigger`, and `MenubarSubContent` for nested menus." },
      source: { code: SubmenuSource },
    },
  },
  render: SubmenuExample,
};

export const WithIcons: Story = {
  parameters: {
    docs: {
      description: { story: "Add icons to menu items to make actions easier to scan." },
      source: { code: WithIconsSource },
    },
  },
  render: WithIconsExample,
};

